"""HyGRAG's QuALITY option extractor, copied verbatim (zjunet/HyGRAG @ fa1a57e, CLOSE_EXTRACT_OPTION_PORMPT in
Core/Utils/Evaluation.py; byte-identical to the copy in run_evaluation.py). HyGRAG formats it with
question=<question with options> and model_output=<the answer>, sends it with format="json" and reads
response["predict"]; "-1" means no option. Extracted from the source text (Evaluation.py itself does not
compile upstream: line 505 has curly quotes), so the string is byte-identical, typos included.
"""
CLOSE_EXTRACT_OPTION_PROMPT = '\nYou are given a model output which is a string. The model output is a list of options. You have to extract the option letter from the model output.\n\n# GOAL\n\nYour goal is to extract the option letter directly from the model output. You should not rely on any external knowledge or context to answer. Simply extract the option letter as stated in the model output.\n\n# FORMAT\n\nPlease provide your answer in the following JSON format:\n\n- ANSWER_OPTION: the option letter extracted from the model output.\n\n    {{\n        "model_output": <answer_option>\n    }}\n\n### Example 1\n-----------\n# INPUT:\n\nQuestion:\nHow much time has passed between Blake\'s night with Eldoria and his search for Sabrina York in his mind-world?\nA: 7 years\nB: 10 hours\nC: 12 years\nD: 1 hour\n\n# Model Output: \nI think the answer is 7 years.\n\nOUTPUT:\n    {{\n        "predict": "A"\n    }}\n\n### Example 2\n-----------\n# INPUT:\n\nQuestion:\nHow much time has passed between Blake\'s night with Eldoria and his search for Sabrina York in his mind-world?\nA: 7 years\nB: 10 hours\nC: 12 years\nD: 1 hour\n\n# Model Output: \nThe correct answer is C.\n\nOUTPUT:\n    {{\n        "predict": "C"\n    }}\n    \n### EXAMPLE 3\n-----------\n\n# INPUT:\n\nQuestion:\nDonald Trump is the president of:\nA: China\nB: Canada\nC: France\nD: Spain\n\n# Model Output: \nThe correct answer is: None of the above.\n\nOUTPUT:\n    {{\n        "predict": "-1"\n    }}\n\nNow please the output based on the given question and model output.\n\n### Real Data\n# INPUT:\n\nQuestion:\n{question}\n\n# Model Output:\n{model_output}\n\nOUTPUT:'
